Lemma parser_at_ws : forall segs (M M' : word -> option byte) (Sg : Z -> Prop) P ps st' p' p e sb' scap' stk',
  (forall a, Sg a -> M' (Z_to_bv 64 a) = M (Z_to_bv 64 a)) ->
  PML.ps_win ps = Some (p, e) -> p' <= e ->
  PTA.out Sg P 160 -> PTA.out Sg (P + 192) 8 -> PTA.out Sg (P + 209) 39 -> PTA.out Sg (PML.ps_bptr ps) (PML.ps_bcap ps) ->
  PMLA.parser_at segs IC M P ps ->
  L5.u64_at segs M' (P + 200) p' -> L5.u8_at segs M' (P + 208) st' ->
  L5.u64_at segs M' (P + 248) sb' -> L5.u64_at segs M' (P + 256) (sb' + Z.of_nat (length stk')) -> L5.u64_at segs M' (P + 264) (sb' + scap') ->
  L5.bytes_at segs M' sb' stk' -> Z.of_nat (length stk') <= scap' ->
  (forall i, 0 <= i < 272 -> M' (Z_to_bv 64 (P + i)) <> None) ->
  PMLA.parser_at segs IC M' P (PML.PS st' (PML.ps_sst ps) (PML.ps_nst ps) (PML.ps_more ps) (PML.ps_done ps) (PML.ps_level ps) stk' sb' scap'
                               (PML.ps_bcap ps) (PML.ps_bptr ps) (PML.ps_buf ps) (Some (p', e))).
